import os, pty, sys, time, select, json, signal, termios, struct, fcntl

def run(cmd, inputs=None, env=None, term=None, delay=0.35, cols=80, rows=24, total_timeout=15.0, send_eof_at_end=True):
    """inputs: list of bytes to write, each followed by `delay` wait."""
    e = dict(os.environ)
    if env: e.update(env)
    if term is not None: e["TERM"] = term
    out = []
    pid, fd = pty.fork()
    if pid == 0:
        os.execvpe("/bin/sh", ["/bin/sh", "-c", cmd], e)
        os._exit(127)
    # set window size
    try:
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    except Exception:
        pass
    def drain(t=0.3):
        end = time.time() + t
        while time.time() < end:
            r,_,_ = select.select([fd], [], [], max(0, end-time.time()))
            if fd in r:
                try:
                    d = os.read(fd, 65536)
                except OSError:
                    return False
                if not d: return False
                out.append(d)
        return True
    alive = drain(delay)
    if inputs:
        for chunk in inputs:
            if not alive: break
            try:
                os.write(fd, chunk)
            except OSError:
                break
            alive = drain(delay)
    if send_eof_at_end and alive:
        try:
            os.write(fd, b"\x04")
        except OSError:
            pass
        drain(delay)
    # final drain
    end = time.time() + 2.0
    while time.time() < end:
        r,_,_ = select.select([fd], [], [], 0.2)
        if fd in r:
            try:
                d = os.read(fd, 65536)
            except OSError:
                break
            if not d: break
            out.append(d)
        else:
            # check child
            p, st = os.waitpid(pid, os.WNOHANG)
            if p == pid:
                # drain remaining
                while True:
                    r,_,_ = select.select([fd],[],[],0.2)
                    if fd not in r: break
                    try: d = os.read(fd, 65536)
                    except OSError: break
                    if not d: break
                    out.append(d)
                os.close(fd)
                return b"".join(out), (os.waitstatus_to_exitcode(st) if hasattr(os,'waitstatus_to_exitcode') else st)
    try:
        os.close(fd)
    except OSError:
        pass
    try:
        p, st = os.waitpid(pid, 0)
        code = os.waitstatus_to_exitcode(st)
    except ChildProcessError:
        code = None
    return b"".join(out), code

if __name__ == "__main__":
    cmd = sys.argv[1]
    inputs = [x.encode().decode('unicode_escape').encode('latin-1') for x in sys.argv[2:]]
    data, code = run(cmd, inputs)
    print("EXIT:", code)
    print("BYTES:", repr(data))
